#if !REFLECTIFY_COMPILE
// <autogenerated />
#pragma warning disable
#endif

#nullable disable

using System;
using System.Linq;
using System.Reflection;

namespace Reflectify;

#if REFLECTIFY_COMPILE
public static class MemberInfoExtensions
#else
[global::Microsoft.CodeAnalysis.Embedded]
[global::System.Diagnostics.DebuggerNonUserCode]
internal static class MemberInfoExtensions
#endif
{
    public static bool HasAttribute<TAttribute>(this MemberInfo member)
        where TAttribute : Attribute
    {
        // Do not use MemberInfo.IsDefined
        // There is an issue with PropertyInfo and EventInfo preventing the inherit option to work.
        // https://github.com/dotnet/runtime/issues/30219
        return Attribute.IsDefined(member, typeof(TAttribute), inherit: false);
    }

    /// <summary>
    /// Determines whether the member has an attribute of the specified type that matches the predicate.
    /// </summary>
    public static bool HasAttribute<TAttribute>(this MemberInfo member, Func<TAttribute, bool> predicate)
        where TAttribute : Attribute
    {
        if (predicate is null)
        {
            throw new ArgumentNullException(nameof(predicate));
        }

        return member.GetCustomAttributes<TAttribute>().Any(a => predicate(a));
    }

    public static bool HasAttributeInHierarchy<TAttribute>(this MemberInfo member)
        where TAttribute : Attribute
    {
        // Do not use MemberInfo.IsDefined
        // There is an issue with PropertyInfo and EventInfo preventing the inherit option to work.
        // https://github.com/dotnet/runtime/issues/30219
        return Attribute.IsDefined(member, typeof(TAttribute), inherit: true);
    }

    /// <summary>
    /// Returns <see langword="true" /> if the member or, by default, its declaring type is marked as obsolete.
    /// </summary>
    /// <param name="member">The member to inspect.</param>
    /// <param name="includeDeclaringType">
    /// Indicates whether obsolescence of the declaring type should also mark the member as obsolete.
    /// </param>
    public static bool IsObsolete(this MemberInfo member, bool includeDeclaringType = true)
    {
        return member.HasAttribute<ObsoleteAttribute>() ||
               (includeDeclaringType && member.DeclaringType?.IsObsolete() == true);
    }

    /// <summary>
    /// Returns <see langword="true" /> if the member is marked with the C# 11 <see langword="required" />
    /// modifier, or <see langword="false" /> otherwise.
    /// </summary>
    /// <remarks>
    /// The C# compiler emits a <c>System.Runtime.CompilerServices.RequiredMemberAttribute</c> on the member itself
    /// as well as on its declaring type. This method only inspects the attribute on the member itself; it does not
    /// check whether the declaring type as a whole is marked as having required members. On older target
    /// frameworks that attribute type may not be part of the BCL and could instead come from a
    /// PolySharp-polyfilled assembly, so it is matched by full name instead of comparing Type instances
    /// (which would fail across assemblies).
    /// </remarks>
    public static bool IsRequired(this MemberInfo member)
    {
        return member.CustomAttributes.Any(attribute =>
            attribute.AttributeType.FullName == "System.Runtime.CompilerServices.RequiredMemberAttribute");
    }
}
